from taf.gnb.oam.megazone_client import megazone_client
from taf.gnb.oam.megazone_client.exceptions import AlarmPresentException, TimeoutError

try:
    import unittest2 as unittest
except ImportError:
    import unittest

try:
    from mock import Mock, patch
except ImportError:
    from unittest.mock import Mock, patch


class_prefix = "taf.gnb.oam.megazone_client.alarms_endpoint.AlarmsEndpoint"
get_active_fault_number_path = class_prefix + ".get_active_faults_number"
get_active_faults_path = class_prefix + ".get_active_faults"


@patch("taf.gnb.oam.megazone_client.alarms_endpoint.time.sleep")
class TestBTSWithActiveFaults(unittest.TestCase):
    def setUp(self):
        self.cor = megazone_client()
        session_mock = Mock()
        self.cor.session_handler = session_mock
        self.cor.session_store.add(session_mock)

    @patch(get_active_faults_path, return_value=[{'additionalText1': '20 Alert'}])
    def test_wait_for_fault_shouldRaiseTimeoutError(self, m_sleep, m_faults):
        fault_no = 10
        with self.assertRaises(TimeoutError):
            self.cor.wait_for_fault(fault_no)

    @patch(get_active_faults_path, return_value=[{'additionalText1': '10 Alert'}])
    def test_wait_for_fault_shouldPass(self, m_sleep, m_faults):
        fault_no = 10
        self.cor.wait_for_fault(fault_no)

    @patch(get_active_faults_path, return_value=[{'additionalText1': '10 Alert',
                                                  'additionalText8': 'Source'}])
    def test_wait_for_fault_whenSourcePassed_shouldWaitOnlyForRelevantFault(
            self, m_sleep, m_faults):
        fault_no = 10
        self.cor.wait_for_fault(fault_no, source='source')

    @patch(get_active_faults_path, return_value=[{'additionalText1': '10 Alert',
                                                  'additionalText8': 'Source'}])
    def test_wait_for_fault_whenSourcePassedAndNotExists_raisesTimeoutError(
            self, m_sleep, m_faults):
        fault_no = 10
        with self.assertRaises(TimeoutError):
            self.cor.wait_for_fault(fault_no, source='nonexistent')

    @patch(get_active_faults_path, return_value=[{'additionalText1': '10 Alert'}])
    def test_wait_for_fault_to_disappear_shouldRaiseTimeoutError(self, m_sleep, m_faults):
        fault_no = 10
        with self.assertRaises(TimeoutError):
            self.cor.wait_for_fault_to_disappear(fault_no)

    @patch(get_active_faults_path, return_value=[{'additionalText1': '10 Alert',
                                                  'additionalText8': 'Source'}])
    def test_waitForFaultToDisappear_whenSourceSpecified_shouldRaiseTimeoutError(
            self, m_sleep, m_faults):
        fault_no = 10
        with self.assertRaises(TimeoutError):
            self.cor.wait_for_fault_to_disappear(fault_no, source='source')

    @patch(get_active_faults_path, return_value=[{'additionalText1': '20 Alert'}])
    def test_wait_for_fault_to_disappear_shouldPass(self, m_sleep, m_faults):
        fault_no = 10
        self.cor.wait_for_fault_to_disappear(fault_no)

    @patch(get_active_faults_path, return_value=[{}, {}])
    def test_get_active_faults_number_shouldEqualNumberOfActiveFaults(self, m_sleep, m_active):
        self.assertEqual(2, self.cor.get_active_faults_number())

    @patch(get_active_fault_number_path, return_value=7)
    def test_check_active_faults_shouldFail(self, m_sleep, m_active):
        with self.assertRaises(AlarmPresentException):
            self.cor.check_active_faults()

    @patch(get_active_fault_number_path, return_value=7)
    def test_check_active_faults_when_allowing_negative_results_shouldPass(self, m_sleep, m_active):
        self.cor.check_active_faults(allow_negative_result=True)
